def check_file_sizes(directory):
    issues = []
    for filename in os.listdir(directory):
        filepath = os.path.join(directory, filename)
        size = os.path.getsize(filepath)
        if size == 0:
            issues.append(f"Zero bytes: {filename}")
        elif size < 100:  # Suspiciously small
            issues.append(f"Very small ({size} bytes): {filename}")
    return issues

chic_issues = check_file_sizes('data_small/Chic')
duck_issues = check_file_sizes('data_small/Duck')

print(f"Chic issues: {len(chic_issues)}")
if chic_issues:
    print(f"  {chic_issues[:5]}")

print(f"Duck issues: {len(duck_issues)}")
if duck_issues:
    print(f"  {duck_issues[:5]}")"}

