import binascii

def examine_file_content(directory, filename):
    filepath = os.path.join(directory, filename)
    with open(filepath, 'rb') as f:
        header = f.read(16)
    return binascii.hexlify(header).decode('ascii')

# Check a few files
print("Chic file headers:")
for f in ['aug_0_7815.png', 'aug_0_2304.png', 'aug_0_5943.png']:
    print(f"  {f}: {examine_file_content('data_small/Chic', f)}")

